import { useEffect, useState } from "react";
import axios from "axios";

export default function Courses() {
  const [courses, setCourses] = useState([]);
  const [quiz, setQuiz] = useState([]);
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    axios
      .get("/api/students/1/enrollments")
      .then((res) => setCourses(res.data))
      .catch((err) => console.log(err));
  }, []);

  const generateQuiz = async () => {
    const res = await axios.get("/api/quiz/generate/DBMS");

    if (Array.isArray(res.data.quiz)) {
      setQuiz(res.data.quiz);
    } else {
      console.log("Invalid quiz format:", res.data.quiz);
      setQuiz([]);
    }

    setAnswers({});
    setSubmitted(false);
  };

  // store selected option index (0,1,2,3)
  const handleSelect = (qIndex, optionIndex) => {
    setAnswers({ ...answers, [qIndex]: optionIndex });
  };

  const submitQuiz = () => {
    setSubmitted(true);
  };

  // ✅ correct score logic
  const score = quiz.reduce((acc, q, i) => {
    return acc + (answers[i] === q.answerIndex ? 1 : 0);
  }, 0);

  return (
    <div className="p-6">
      <h1 className="text-xl font-bold mb-4">My Courses</h1>

      {/* Generate Quiz Button */}
      <button
        onClick={generateQuiz}
        className="bg-green-500 text-white px-4 py-2 rounded mb-4"
      >
        Generate AI Quiz
      </button>

      {/* Quiz Section */}
      {quiz.map((q, i) => (
        <div key={i} className="mb-6 border p-4 rounded bg-white">
          <h2 className="font-semibold mb-2">
            Q{i + 1}. {q.question}
          </h2>

          {q.options.map((opt, j) => (
            <label key={j} className="block">
              <input
                type="radio"
                name={`q-${i}`}
                disabled={submitted}
                onChange={() => handleSelect(i, j)} // ✅ FIXED
              />
              <span className="ml-2">{opt}</span>
            </label>
          ))}

          {/* Result */}
          {submitted && (
            <div className="mt-2">
              {answers[i] === q.answerIndex ? (
                <p className="text-green-600 font-semibold">
                  Correct ✅
                </p>
              ) : (
                <>
                  <p className="text-red-600 font-semibold">
                    Wrong ❌ (Correct: {q.options[q.answerIndex]})
                  </p>
                  <p className="text-gray-600 text-sm">
                    {q.explanation}
                  </p>
                </>
              )}
            </div>
          )}
        </div>
      ))}

      {/* Submit Button */}
      {quiz.length > 0 && !submitted && (
        <button
          onClick={submitQuiz}
          className="bg-blue-500 text-white px-4 py-2 rounded"
        >
          Submit Quiz
        </button>
      )}

      {/* Score */}
      {submitted && (
        <h2 className="mt-4 text-lg font-bold">
          Score: {score} / {quiz.length}
        </h2>
      )}
    </div>
  );
}
